<?php require_once __DIR__.'/../includes/bootstrap.php'; $base='../'; $items=$_SESSION['cart']??[]; $subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items)); $shipping=$items?15000:0; $total=$subtotal+$shipping; ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Giỏ hàng & Thanh toán - Tạp Hóa Online</title><link rel="stylesheet" href="../assets/css/style-cart.css"></head><body><?php require __DIR__.'/../includes/site-header.php'; ?><main class="container page-layout"><aside class="sidebar"><div class="sidebar-box"><h3 class="box-title">☷ Danh mục hàng hóa</h3><ul class="cat-list"><?php foreach(db()->query('SELECT * FROM categories ORDER BY name') as $c): ?><li><a href="products.php?category=<?=$c['id']?>"><?=e($c['name'])?></a></li><?php endforeach; ?></ul></div></aside><section class="content-area"><h2 class="section-title">🛒 Giỏ hàng & Thanh toán</h2><?php if(!$items): ?><div class="checkout-card empty-cart-box"><div class="empty-cart-icon">🛒</div><p class="empty-cart-text">Giỏ hàng của bạn đang trống.</p><a href="products.php" class="btn-continue-shopping">Tiếp tục mua hàng</a></div><?php else: ?><div class="checkout-grid"><div class="checkout-card"><h3 class="card-title">👤 Thông tin giao hàng</h3><form method="post" action="../actions/order.php"><div class="form-group"><label>Họ và tên người nhận *</label><input name="customer_name" placeholder="Tên người nhận" required></div><div class="form-row"><div class="form-group"><label>Số điện thoại *</label><input name="phone" placeholder="Số điện thoại" required></div><div class="form-group"><label>Email</label><input type="email" name="email" placeholder="Email người nhận"></div></div><div class="form-group"><label>Địa chỉ giao hàng *</label><input name="address" placeholder="Số nhà, tên đường, phường/xã, quận/huyện..." required></div><div class="form-group"><label>Ghi chú cho shipper</label><textarea name="note" rows="2" placeholder="Ví dụ: Giao giờ hành chính..."></textarea></div><h3 class="card-title">💳 Phương thức thanh toán</h3><div class="payment-methods"><label class="payment-option"><input type="radio" name="payment_method" value="cod" checked> Thanh toán khi nhận hàng (COD)</label><label class="payment-option"><input type="radio" name="payment_method" value="banking"> Chuyển khoản ngân hàng</label></div><button class="btn-checkout">📨 ĐẶT HÀNG NGAY</button></form></div><div class="checkout-card"><h3 class="card-title">☷ Đơn hàng của bạn</h3><div class="cart-items-container"><?php foreach($items as $i): ?><div class="cart-item"><img src="<?=e($i['image_url'])?>" alt="<?=e($i['name'])?>"><div class="item-info"><div class="item-title"><?=e($i['name'])?></div><div class="item-price"><?=number_format($i['price'],0,',','.')?> đ × <?=$i['quantity']?></div></div><a class="btn-delete" href="../actions/cart.php?action=remove&product_id=<?=$i['id']?>">×</a></div><?php endforeach; ?></div><form method="post" action="../actions/cart.php"><input type="hidden" name="action" value="update"><div class="form-group"><label>Cập nhật số lượng</label><?php foreach($items as $i): ?><input type="number" min="1" name="quantities[<?=$i['id']?>]" value="<?=$i['quantity']?>" aria-label="Số lượng <?=e($i['name'])?>"><?php endforeach; ?></div><button class="btn-secondary">Cập nhật giỏ hàng</button></form><div class="order-summary"><div class="summary-line"><span>Tạm tính:</span><span><?=number_format($subtotal,0,',','.')?> đ</span></div><div class="summary-line"><span>Phí giao hàng:</span><span><?=number_format($shipping,0,',','.')?> đ</span></div><div class="summary-line total-line"><span>Tổng thanh toán:</span><span><?=number_format($total,0,',','.')?> đ</span></div></div></div></div><?php endif; ?></section></main><?php require __DIR__.'/../includes/site-footer.php'; ?></body></html>
